'use client'

import { cn } from '@gentleduck/libs/cn'
import * as AccordionPrimitive from '@gentleduck/primitives/accordion'
import { ChevronDown } from 'lucide-react'
import * as React from 'react'

const AccordionRenderOnceContext = React.createContext(false)

export type IAccordionProps = AccordionPrimitive.IAccordion.IProps & {
  renderOnce?: boolean
}

export type AccordionProps = IAccordionProps

const Accordion = React.forwardRef<HTMLDivElement, IAccordionProps>(
  ({ className, renderOnce = false, ...props }, ref) => (
    <AccordionRenderOnceContext.Provider value={renderOnce}>
      <AccordionPrimitive.Root
        ref={ref}
        className={cn('min-w-100 font-sans not-italic [interpolate-size:allow-keywords]', className)}
        {...props}
      />
    </AccordionRenderOnceContext.Provider>
  ),
)
Accordion.displayName = 'Accordion'

const AccordionItem = React.forwardRef<HTMLDivElement, React.ComponentPropsWithoutRef<typeof AccordionPrimitive.Item>>(
  ({ className, ...props }, ref) => (
    <AccordionPrimitive.Item
      ref={ref}
      className={cn('group overflow-hidden border-border border-b', className)}
      {...props}
    />
  ),
)
AccordionItem.displayName = 'AccordionItem'

const AccordionTrigger = React.forwardRef<
  HTMLButtonElement,
  React.ComponentPropsWithoutRef<typeof AccordionPrimitive.Trigger> & {
    icon?: React.ReactNode
  }
>(({ className, children, icon, ...props }, ref) => {
  return (
    <AccordionPrimitive.Trigger
      ref={ref}
      className={cn(
        'group/accordion-trigger flex w-full cursor-pointer select-none items-center justify-between py-4 text-start font-medium font-sans text-base not-italic ring-offset-background transition-all hover:underline focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2',
        className,
      )}
      {...props}>
      <span>{children}</span>
      <span
        className={cn(
          '[&>svg:not([class*=size-])]:size-4 [&>svg]:shrink-0 [&>svg]:transition-transform [&>svg]:duration-200 group-data-[state=open]/accordion-trigger:[&>svg]:rotate-180',
        )}
        data-slot="accordion-icon">
        {icon ? icon : <ChevronDown aria-hidden="true" />}
      </span>
    </AccordionPrimitive.Trigger>
  )
})
AccordionTrigger.displayName = 'AccordionTrigger'

const AccordionContent = React.forwardRef<
  HTMLDivElement,
  Omit<React.ComponentPropsWithoutRef<typeof AccordionPrimitive.Content>, 'asChild' | 'forceMount'> & {
    rerender?: boolean
  }
>(({ className, children, rerender: _rerender = false, ...props }, ref) => {
  const renderOnce = React.useContext(AccordionRenderOnceContext)
  const { open } = AccordionPrimitive.useAccordionItemContext('AccordionContent', undefined)
  const [hasOpened, setHasOpened] = React.useState(open)

  React.useEffect(() => {
    if (open) setHasOpened(true)
  }, [open])

  if (renderOnce && !hasOpened) return null

  return (
    <AccordionPrimitive.Content
      ref={ref}
      forceMount
      inert={!open || undefined}
      className={cn(
        'block overflow-hidden font-sans text-base not-italic will-change-[height,opacity]',
        'data-[state=closed]:h-0 data-[state=open]:h-auto',
        'data-[state=closed]:opacity-0 data-[state=open]:opacity-100',
        'data-[state=closed]:pointer-events-none',
        'transition-[height,opacity] duration-[200ms,150ms] ease-(--gentleduck-motion-ease)',
        'motion-reduce:transition-none',
        className,
      )}
      {...props}>
      <div className="pt-0 pb-4">{children}</div>
    </AccordionPrimitive.Content>
  )
})
AccordionContent.displayName = 'AccordionContent'

export { Accordion, AccordionContent, AccordionItem, AccordionRenderOnceContext, AccordionTrigger }

export type { AccordionProps, IAccordionProps } from './accordion'
export {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from './accordion'
export {
  MotionAccordion,
  MotionAccordionContent,
  MotionAccordionItem,
  MotionAccordionTrigger,
} from './motion-accordion'

'use client'

import { cn } from '@gentleduck/libs/cn'
import { getStaggerDelay } from '@gentleduck/motion'
import { loadDomAnimation } from '@gentleduck/motion/motion-features'
import { useMotionPreset } from '@gentleduck/motion/motion-presets'
import { heightAuto } from '@gentleduck/motion/presets/height-auto'
import { scaleIn } from '@gentleduck/motion/presets/scale-in'
import { springBouncy } from '@gentleduck/motion/transitions/springs'
import { duckMotionDuration, tweenExpand } from '@gentleduck/motion/transitions/tweens'
import * as AccordionPrimitive from '@gentleduck/primitives/accordion'
import { ChevronDown } from 'lucide-react'
import { LazyMotion, m } from 'motion/react'
import * as React from 'react'
import type { IAccordionProps } from './accordion'
import { Accordion, AccordionRenderOnceContext } from './accordion'

const MotionAccordionItem = React.forwardRef<
  HTMLDivElement,
  Omit<React.ComponentPropsWithoutRef<typeof AccordionPrimitive.Item>, 'asChild'> & {
    index?: number
  }
>(({ className, children, index = 0, ...props }, ref) => {
  const presetOptions = React.useMemo(() => ({ transition: springBouncy, delay: getStaggerDelay(index, 50) }), [index])
  const content = useMotionPreset(scaleIn, presetOptions)

  return (
    <LazyMotion features={loadDomAnimation}>
      <AccordionPrimitive.Item asChild {...props}>
        <m.div
          ref={ref}
          className={cn('group overflow-hidden border-border border-b', className)}
          initial={content.initial}
          animate={content.animate}
          transition={content.transition}>
          {children}
        </m.div>
      </AccordionPrimitive.Item>
    </LazyMotion>
  )
})
MotionAccordionItem.displayName = 'MotionAccordionItem'

const MotionAccordion = React.forwardRef<HTMLDivElement, IAccordionProps>(({ children, ...props }, ref) => {
  let index = 0
  const total = React.Children.toArray(children).filter(
    (child) => React.isValidElement(child) && child.type === MotionAccordionItem,
  ).length

  const injectIndex = (child: React.ReactNode): React.ReactNode => {
    if (React.isValidElement(child) && child.type === MotionAccordionItem) {
      return React.cloneElement(child as React.ReactElement<{ index?: number; total?: number }>, {
        index: index++,
        total,
      })
    }

    return child
  }

  return (
    <Accordion ref={ref} {...props}>
      {React.Children.map(children, injectIndex)}
    </Accordion>
  )
})
MotionAccordion.displayName = 'MotionAccordion'

const MotionAccordionTrigger = React.forwardRef<
  HTMLButtonElement,
  Omit<React.ComponentPropsWithoutRef<typeof AccordionPrimitive.Trigger>, 'asChild'> & {
    icon?: React.ReactNode
  }
>(({ className, children, icon, ...props }, ref) => {
  const { open } = AccordionPrimitive.useAccordionItemContext('MotionAccordionTrigger', undefined)
  const content = useMotionPreset(scaleIn, { transition: springBouncy })

  return (
    <LazyMotion features={loadDomAnimation}>
      <AccordionPrimitive.Trigger asChild {...props}>
        <m.button
          ref={ref}
          className={cn(
            'flex w-full cursor-pointer select-none items-center justify-between py-4 font-medium font-sans text-base not-italic ring-offset-background transition-all hover:underline focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2',
            className,
          )}>
          <m.span
            initial={content.initial}
            animate={content.animate}
            transition={content.transition}
            className="flex-1 text-left">
            {children}
          </m.span>
          <m.span
            animate={{ rotate: open ? 180 : 0 }}
            transition={tweenExpand}
            className="ml-2 [&>svg:not([class*='size-'])]:size-4 [&>svg]:shrink-0"
            data-slot="accordion-icon">
            {icon ? icon : <ChevronDown aria-hidden="true" />}
          </m.span>
        </m.button>
      </AccordionPrimitive.Trigger>
    </LazyMotion>
  )
})
MotionAccordionTrigger.displayName = 'MotionAccordionTrigger'

const MotionAccordionContent = React.forwardRef<
  HTMLDivElement,
  Omit<React.ComponentPropsWithoutRef<typeof AccordionPrimitive.Content>, 'asChild' | 'forceMount'>
>(({ className, children, ...props }, ref) => {
  const renderOnce = React.useContext(AccordionRenderOnceContext)
  const { open } = AccordionPrimitive.useAccordionItemContext('MotionAccordionContent', undefined)
  const [hasOpened, setHasOpened] = React.useState(open)

  React.useEffect(() => {
    if (open) setHasOpened(true)
  }, [open])

  if (renderOnce && !hasOpened) return null

  return (
    <LazyMotion features={loadDomAnimation}>
      <AccordionPrimitive.Content forceMount asChild inert={!open || undefined} {...props}>
        <m.div
          ref={ref}
          animate={open ? heightAuto.open : heightAuto.closed}
          initial={open ? heightAuto.open : heightAuto.closed}
          transition={{
            height: tweenExpand,
            opacity: { duration: duckMotionDuration.normal, delay: open ? 0.05 : 0 },
            filter: { duration: duckMotionDuration.normal, delay: open ? 0.05 : 0 },
          }}
          style={{ overflow: 'hidden' }}>
          <div className={cn('pt-0 pb-4 font-sans text-base not-italic', className)}>{children}</div>
        </m.div>
      </AccordionPrimitive.Content>
    </LazyMotion>
  )
})
MotionAccordionContent.displayName = 'MotionAccordionContent'

export { MotionAccordion, MotionAccordionContent, MotionAccordionItem, MotionAccordionTrigger }
